using NovaHarvest.Core.Models;using NovaHarvest.Core.NPC.Characters;using NovaHarvest.Core.Systems;using NovaHarvest.Core.World;var game=new GameSession(5,5,42);Console.WriteLine("=== NOVA HARVEST CORE DEMO ===");Console.WriteLine($"Dia {game.Time.Day} - {game.Time.GetFormattedTime()} - {game.Time.CurrentPeriod}");Console.WriteLine($"Objetos: {game.World.ObjectCount}");Console.WriteLine($"NPCs: {game.NPCs.AllNPCs.Count}");var crafted=game.Crafting.Craft("craft_farm_plot");Console.WriteLine($"Craft canteiro: {crafted}");var built=game.Building.BuildFarmPlotNearPlayer();Console.WriteLine($"Construção: {built}");var farm=game.World.Objects.OfType<FarmPlotObject>().LastOrDefault();if(farm is not null){Console.WriteLine($"Plantio: {game.Farming.Plant(farm.Plot,"seed_lumen_berry")}");game.Farming.Water(farm.Plot,game.Time.Day);game.Time.StartNextDay();game.Farming.Water(farm.Plot,game.Time.Day);game.Time.StartNextDay();game.Farming.Water(farm.Plot,game.Time.Day);game.Time.StartNextDay();Console.WriteLine($"Estado da planta: {farm.Plot.State}");if(game.Farming.Harvest(farm.Plot,out var amount))Console.WriteLine($"Colheita: Lumen Berry x{amount}");}var lyra=game.NPCs.Find("npc_lyra");if(lyra is not null){lyra.Discover();lyra.Rescue();var q=game.Quests.Find("quest_lyra_first_contact");q?.Start();q?.AddProgress("find_lumen_seeds",3);q?.AddProgress("find_green_crystal",1);q?.AddProgress("build_farm_plot",1);Console.WriteLine($"Quest concluída: {game.Quests.CompleteQuest("quest_lyra_first_contact")}");Console.WriteLine($"Lyra friendship: {lyra.Relationship.Friendship}");Console.WriteLine($"Alien botany: {game.Progression.IsUnlocked("alien_botany")}");}
